{
  "verdict": "SUPPORTED",
  "reason": "The script facts accurately reflect the sequence of fire, water immersion, pyrotechnics, night boat operations, and the presence of child and animal characters depicted across scenes S009-S011. The cited industry safety bulletins support the conditional remedies for licensed pyrotechnic operations, water safety personnel/devices, hypothermia mitigation, and animal/minor staging safeguards.",
  "failure_mode": "none",
  "claim_checks": [
    {
      "field": "finding",
      "quote": "Scenes S009, S010, and S011 depict a heavily stacked sequence of physical hazards taking place in open harbor waters at night.",
      "basis": "script",
      "status": "SUPPORTED",
      "reason": "Accurately summarizes the action and setting in scenes S009, S010, and S011.",
      "citation_numbers": [],
      "support_spans": [],
      "script_spans": [
        "EXT. BANNOCK HARBOR - NIGHT",
        "Mara stands, braces, and fires the flare into the soaked blankets amidships."
      ]
    },
    {
      "field": "finding",
      "quote": "The staged action includes discharging a flare gun into fuel-soaked blankets on an anchored vessel (Margaret Rose), causing an engulfing fire and diesel burn, adjacent aerial mortar fireworks launched from the seawall, a severed anchor line causing the burning vessel to drift toward moored floats, a character (Mara) diving into cold water at night to swim a line to a mooring buoy, boat maneuvers adjacent to flames to tow the vessel, and an adjacent skiff carrying a child character (Sam) and a dog (Barnacle).",
      "basis": "script",
      "status": "SUPPORTED",
      "reason": "Directly matches the depicted narrative actions across S009-S011.",
      "citation_numbers": [],
      "support_spans": [],
      "script_spans": [
        "Sam in the bow in a life vest two sizes too big, one hand knotted in Barnacle's collar. The old dog rides like a figurehead, nose into the wind.",
        "Mara stands, braces, and fires the flare into the soaked blankets amidships.",
        "Then the diesel catches and the MARGARET ROSE goes up -- a column of fire standing on the black water, doubled in the swell, huge.",
        "Crow touches a road flare to the mortar fuse. The Fourth of July stash goes up -- white and gold chrysanthemums blooming over the burning boat",
        "The anchor line, burned through at the chock, parts. The burning boat swings free and begins to drift",
        "she DIVES -- off the skiff into the black water, surfacing in the firelight, swimming hard for the mooring buoy off the Margaret Rose's bow.",
        "Danny throws the skiff into gear, takes up the slack, and eases the burning boat's head around -- slow, straining, the flames roaring overhead"
      ]
    },
    {
      "field": "finding",
      "quote": "While the script depicts these story events, practical versus visual effects execution, shooting jurisdiction, casting ages, and marine safety protocols remain unconfirmed production decisions.",
      "basis": "production",
      "status": "SUPPORTED",
      "reason": "Correctly identifies production parameters as unconfirmed rather than asserting unevidenced production facts.",
      "citation_numbers": [],
      "support_spans": []
    },
    {
      "field": "remedy",
      "quote": "If practical fire, flare discharge, or fireworks are utilized, engage a licensed Pyrotechnic Special Effects Operator and obtain required permits from the Authority Having Jurisdiction (AHJ) in compliance with CSATF Safety Bulletin #16; alternatively, execute the vessel burn, flare ignition, and mortar fireworks using CGI/VFX or controlled tank/miniature elements to eliminate live open-water fire hazards.",
      "basis": "planning",
      "status": "SUPPORTED",
      "reason": "CSATF Safety Bulletin #16 explicitly requires permits from AHJ and licensed Pyrotechnic Special Effects Operators when pyrotechnic materials are used.",
      "citation_numbers": [1],
      "support_spans": [
        {
          "citation_number": 1,
          "quote": "Any required licenses and/or permits shall be obtained from proper Authorities Having Jurisdiction (AHJ) over pyrotechnic materials prior to using pyrotechnic special effects. Pyrotechnic Special Effects Operator(s) must hold valid State and Federal license(s), as applicable."
        }
      ]
    },
    {
      "field": "remedy",
      "quote": "For practical night water work and the depicted swimming stunt, engage a Marine Coordinator and dedicated Water Safety / Lifesaving personnel per CSATF Safety Bulletin #17 and #15. Provide appropriate personal flotation devices, buddy/personnel accounting systems, qualified stunt doubles for the dive and tow sequence, and active hypothermia mitigation measures (including warm staging areas/tents, heated dry suits or thermal layers, and immediate medical standby).",
      "basis": "planning",
      "status": "SUPPORTED",
      "reason": "CSATF Safety Bulletin #17 and Actsafe Safety Bulletin #17 support water safety devices, buddy/accounting systems, and hypothermia prevention measures for personnel in water.",
      "citation_numbers": [2, 3, 5],
      "support_spans": [
        {
          "citation_number": 2,
          "quote": "Appropriate water safety devices (e.g., life vests, life preservers, safety rings, safety hooks, buoys) should be available for all personnel working in or around water. When necessary, the Production Management should implement a plan to account for personnel in the water, such as a “buddy” or a check in/check out system."
        },
        {
          "citation_number": 3,
          "quote": "The Producer should take steps to prevent hyperthermia (elevated body temperature) and hypothermia (reduced body temperature)."
        },
        {
          "citation_number": 5,
          "quote": "Guidelines for Boating/Watercraft Safety for Film Crews"
        }
      ]
    },
    {
      "field": "remedy",
      "quote": "Confirm performer casting age and animal handling plans; if a minor performer or live animal is cast, enforce jurisdictional minor working hours and welfare safeguards, provide certified animal handler supervision per CSATF Safety Bulletin #6, or stage the child and animal elements separately from night water and pyrotechnic filming via plates/split-screen.",
      "basis": "planning",
      "status": "SUPPORTED",
      "reason": "Appropriately frames safeguards conditionally on actual live animal and minor performer casting, referencing CSATF Safety Bulletin #6.",
      "citation_numbers": [4],
      "support_spans": [
        {
          "citation_number": 4,
          "quote": "Animal Handling Rules for the Motion Picture Industry"
        }
      ]
    },
    {
      "field": "severity",
      "quote": "HIGH",
      "basis": "risk_assessment",
      "status": "SUPPORTED",
      "reason": "Heavily stacked high-risk practical hazards (night open water swimming, fuel fire, flare, and fireworks) justify a HIGH safety rating.",
      "citation_numbers": [1, 2],
      "support_spans": [
        {
          "citation_number": 1,
          "quote": "When pyrotechnic materials are used on set, such use shall be under controlled conditions with due regard for the safety of all involved."
        },
        {
          "citation_number": 2,
          "quote": "Appropriate water safety devices (e.g., life vests, life preservers, safety rings, safety hooks, buoys) should be available for all personnel working in or around water."
        }
      ],
      "script_spans": [
        "Mara stands, braces, and fires the flare into the soaked blankets amidships.",
        "she DIVES -- off the skiff into the black water, surfacing in the firelight, swimming hard for the mooring buoy off the Margaret Rose's bow."
      ]
    }
  ]
}
